# Let me re-examine the problem more carefully by looking at what changes between inputs and outputs

inputs = ['zfu', 'bfwic', 'jhaihz', 'xjhb', 'gei']
outputs = ['zfu', 'bfybvic', 'jfkzaifkzz', 'xjfkzb', 'gei']

print("Analyzing transformations:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"'{inp}' → '{outp}'")
    if inp != outp:
        # Find differences
        diff_pairs = []
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pairs.append((inp[j], outp[j]))
        # Check for additions/deletions
        if len(inp) != len(outp):
            # Look for longer sequences
            if len(outp) > len(inp):
                # Something was added
                added_chars = outp[len(inp):]
                if len(added_chars) <= 3:
                    diff_pairs.append((inp[-1] if inp else '', added_chars))
            else:
                # Something was removed
                removed_chars = inp[len(outp):]
                if len(removed_chars) <= 3:
                    diff_pairs.append((removed_chars, outp[-1] if outp else ''))
        print(f"  Differences: {diff_pairs}")
    print()

